-- Grants: the API inserts and reads, the worker reads, nobody updates,
-- deletes or truncates; PUBLIC has nothing; RLS is forced.
SELECT pg_temp.check(has_table_privilege('twin_api','twin.ai_proposal_images','SELECT') AND has_table_privilege('twin_api','twin.ai_proposal_images','INSERT')
  AND NOT has_table_privilege('twin_api','twin.ai_proposal_images','UPDATE') AND NOT has_table_privilege('twin_api','twin.ai_proposal_images','DELETE')
  AND NOT has_table_privilege('twin_api','twin.ai_proposal_images','TRUNCATE'), 'the API inserts and reads images only');
SELECT pg_temp.check(has_table_privilege('twin_worker','twin.ai_proposal_images','SELECT') AND NOT has_table_privilege('twin_worker','twin.ai_proposal_images','INSERT')
  AND NOT has_table_privilege('twin_worker','twin.ai_proposal_images','UPDATE') AND NOT has_table_privilege('twin_worker','twin.ai_proposal_images','DELETE'),
  'the worker reads images only');
SELECT pg_temp.check(NOT has_table_privilege('public','twin.ai_proposal_images','SELECT'), 'PUBLIC reads no image');
SELECT pg_temp.check(relrowsecurity AND relforcerowsecurity, 'RLS is forced on images') FROM pg_class WHERE oid = 'twin.ai_proposal_images'::regclass;
SELECT pg_temp.check(NOT has_function_privilege('public','twin.protect_ai_proposal_image()','EXECUTE')
  AND NOT has_function_privilege('public','twin.check_proposal_source()','EXECUTE'), 'PUBLIC calls neither trigger function');

