SELECT pg_temp.proposal('aip_01M4YDQK00TA00000000000031', 'edit', '') \gexec
SELECT pg_temp.image('aip_01M4YDQK00TA00000000000031', '21843', 'image/png', '1200', '520') \gexec
SET CONSTRAINTS ALL IMMEDIATE;
