  VALUES ('org_01M4YDQK00TA00000000000000','aip_01M4YDQK00TA00000000000032','tenant/org_01M4YDQK00TA00000000000000/assets/proposal-images/aip_01M4YDQK00TA00000000000032/image','sha256:1111111111111111111111111111111111111111111111111111111111111111',10,'image/png',64,64)$q$, '55000');
