-- The stored shape: size, type, pixels, hash and key.
SELECT pg_temp.must_fail_at_commit(ARRAY[pg_temp.proposal('aip_01M4YDQK00TA00000000000033', 'edit', ''), s], '23514') FROM unnest(ARRAY[
  pg_temp.image('aip_01M4YDQK00TA00000000000033', '0', 'image/png', '64', '64'),
