  replace(pg_temp.image('aip_01M4YDQK00TA00000000000033', '100', 'image/png', '64', '64'), 'tenant/org_01M4YDQK00TA00000000000000/assets', 'tenant/org_01M4YDQK00TB00000000000000/assets'),
